export enum RegionType {
	None,
	Ocean,
	Landmass,
	Island,
	CoastalIsland,
	_Length,
}

export enum TerrainType {
	Unknown,
	Ocean,
	Coast,
	Flat,
	Rough,
	Mountainous,
	NavRiver,
	_Length,
}

export enum FeatureType {
	None,
	Volcano,
	_Length,
}

export function isLand(terrainType: TerrainType) {
	return (
		terrainType === TerrainType.Flat || terrainType === TerrainType.Rough || terrainType === TerrainType.Mountainous
	);
}

export function isWater(terrainType: TerrainType) {
	return (
		terrainType === TerrainType.Ocean || terrainType === TerrainType.Coast || terrainType === TerrainType.NavRiver
	);
}

export enum BiomeType {
	Unknown,
	Ocean,
	Desert,
	Grassland,
	Plains,
	Tropical,
	Tundra,
	_Length,
}

export enum DetailsType {
	None,
	MinorRiver,
	Wet,
	Vegetated,
	Floodplain,
	Snow,
	_Length,
}

export type PathKey = string | number;
export interface Indexable {
	[key: string]: unknown;
	[key: number]: unknown;
}

export type ConfigValueType = number | boolean;
export interface ConfigValueRecord {
	[key: string]: ConfigValueType | ConfigValueRecord | ConfigValueRecord[];
}

export interface RuleConfigType {
	className: string;
	weight: number;
	isActive: boolean;
	config?: ConfigValueRecord; // Used for overriding rule defaults
}

export type RuleConfigValueRecord = Record<string, Record<string, RuleConfigType>>;

export type ConfigValueFromNode<N extends ParameterSpecNode> = N extends {
	children: infer C extends ParameterSpecRecord;
}
	? ConfigValueRecordTyped<C>[]
	: N extends { default: infer D }
		? D extends boolean
			? boolean // Keeps true/false as boolean type instead of baking to true/false
			: D extends number
				? number
				: D extends string
					? string
					: D
		: never;

export type ConfigValueRecordTyped<TSpecs extends ParameterSpecRecord> = {
	-readonly [K in keyof TSpecs]: ConfigValueFromNode<TSpecs[K]>;
};

export enum VariantOverrideType {
	Replace,
	Add,
	Multiply,
}

export type ParameterSpecNode = ParameterSpec | ParameterSpecGroup;
export type ParameterSpecRecord = Record<string, ParameterSpecNode>;

export interface ParameterSpec {
	visible?: boolean;
	label: string;
	description?: string;
	default: ConfigValueType;
	min?: number;
	max?: number;
	step?: number;
	locked?: boolean; // Causes the UI to be disabled and prevents saving the value out to json.
	unified?: boolean; // For arrays, causes the property to be exposed as a single control unifying all array items.
}

export interface ParameterSpecGroup {
	visible?: boolean;
	label: string;
	description?: string;
	children: ParameterSpecRecord;

	// group spec – disallow leaf level properties
	default?: never;
	min?: never;
	max?: never;
	step?: never;
	locked?: never;
	unified?: never;
}

export enum MapSize {
	Tiny,
	Small,
	Standard,
	Large,
	Huge,
}

export const MapDims: Record<MapSize, { x: number; y: number }> = {
	[MapSize.Tiny]: { x: 60, y: 38 },
	[MapSize.Small]: { x: 74, y: 46 },
	[MapSize.Standard]: { x: 84, y: 54 },
	[MapSize.Large]: { x: 96, y: 60 },
	[MapSize.Huge]: { x: 106, y: 66 },
};

export interface VectorField {
	sampleLatLong(latDeg: number, lonDeg: number): float2; // coordinates are +/- 90 for latitude, +/- 180 for longitude
	sampleUV(u: number, v: number): float2; // 0-1 coordinates
	sampleSigned(x: number, y: number): float2; // -1 to 1 coordinates
}
